import { useState, type FormEvent } from 'react';
import {
  JxTextField,
  JxSelect,
  JxSelectItem,
  JxSwitch,
  JxButton,
} from '@jinx-ui/react';

type InterfaceLanguage = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: InterfaceLanguage;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

const ProfileSettingsForm = ({ onSave }: ProfileSettingsFormProps) => {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<InterfaceLanguage>('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}
    >
      <JxTextField
        label="Имя"
        name="name"
        value={name}
        onChange={(event) => setName(event.target.value)}
        placeholder="Введите имя"
      />

      <JxSelect
        label="Язык интерфейса"
        name="language"
        value={language}
        onValueChange={(value) => setLanguage(value as InterfaceLanguage)}
      >
        <JxSelectItem value="ru">Русский</JxSelectItem>
        <JxSelectItem value="en">English</JxSelectItem>
      </JxSelect>

      <JxSwitch
        label="Уведомления на почту"
        name="emailNotifications"
        checked={emailNotifications}
        onCheckedChange={setEmailNotifications}
      />

      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </form>
  );
};

export default ProfileSettingsForm;

